UPDATE survey_list
   SET title = #{title}, sgg_cd = IFNULL(sgg_cd, #{sggCd}), move_mode = IFNULL(#{moveMode}, move_mode)
 WHERE survey_id = #{surveyId} AND user_id = #{userId}

mapper.delete:
DELETE FROM survey_plan
 WHERE survey_id = #{surveyId}
   AND NOT EXISTS (SELECT 1 FROM survey_record r WHERE r.plan_id = survey_plan.plan_id)

   AND factor_id NOT IN #{id}

DELETE FROM survey_list
 WHERE survey_id = #{surveyId} AND user_id = #{userId}
   AND NOT EXISTS (SELECT 1 FROM survey_plan p JOIN survey_record r ON r.plan_id = p.plan_id WHERE p.survey_id = #{surveyId})
